import { Dex } from '@pkmn/dex'
import { Generations } from '@pkmn/data';
import tierlist from '../data/nlb-season7.json'

export const draftTable = () => {
    const NATDEX_EXISTS = (d, g) => {
        return true
    };

    const gens = new Generations(Dex.includeFormats("natdex"), NATDEX_EXISTS);
    const Gen = gens.get(9)

    return (
        tierlist.map(draft => {
            console.log(draft.name)
            const pokemon = Gen.species.get(draft.name)

            pokemon['abilities'] = Object.values(pokemon['abilities'])
            Gen.learnsets.learnable(pokemon['name']).then(learnset => {
                pokemon['learnset'] = Object.keys(learnset).map(id => {
                    return Gen.moves.get(id).name
                })
            })
            pokemon['cost'] = draft['cost']
            pokemon['isDrafted'] = draft['isDrafted'];

            const k_hp = Math.floor(2*pokemon.baseStats.hp + 141)
            const k_def = Math.floor(2*pokemon.baseStats.def + 36)
            const k_spd = Math.floor(2*pokemon.baseStats.spd + 36)

            pokemon['phys_bulk'] = Math.round(25.22*k_hp/Math.floor(4200*236/(k_def*50)+2))
            pokemon['spc_bulk'] = Math.round(25.22*k_hp/Math.floor(4200*236/(k_spd*50)+2))

            return pokemon;
        })
    );
};

export default draftTable