import React from "react";
import Modal from "react-modal"
import { useReactTable, flexRender, getCoreRowModel, getSortedRowModel, getFilteredRowModel } from "@tanstack/react-table";

import { columnDef } from "./columns";
import draftTable from '../utils/getDraftTable'
import logo from '../assets/nlb-logo.png'

import ColumnSelect from "./ColumnSelect";


const Table = () => {
    const finalData = React.useMemo(() => draftTable(), []);
    const finalColumnDef = React.useMemo(() => columnDef, []);

    const [sorting, setSorting] = React.useState([]);
    const [globalFilter, setGlobalFilter] = React.useState("");
    const [columnFilters, setColumnFilters] = React.useState([]);
    const [columnVisibility, setColumnVisibility] = React.useState({
        "learnset": false,
    });

    const table = useReactTable({
        columns: finalColumnDef,
        data: finalData,
        getCoreRowModel: getCoreRowModel(),
        getSortedRowModel: getSortedRowModel(),
        getFilteredRowModel: getFilteredRowModel(),
        state: {
            sorting: sorting,
            globalFilter: globalFilter,
            columnFilters: columnFilters,
            columnVisibility,
        },
        onSortingChange: setSorting,
        onGlobalFilterChange: setGlobalFilter,
        onColumnFiltersChange: setColumnFilters,
    });

    const [modalIsOpen, setmodalIsOpen] = React.useState(false);

    const handleClose = () => setmodalIsOpen(false);
    const handleOpen = () => setmodalIsOpen(true);

    const [typeFilterValue, setTypeFilterValue] = React.useState('')
    const [abilityFilterValue, setAbilityFilterValue] = React.useState('')
    const [learnsetFilterValue, setLearnsetFilterValue] = React.useState('')

    return (
        <>
            <div className="HeaderBar">
                <img src={logo} className="NlbLogo"/>
                <h1>Stat Compendium</h1>
                <button className="FiltersButton" onClick={handleOpen}>Filters</button>
            </div>
            <Modal 
                isOpen={modalIsOpen}
                onRequestClose={handleClose}
                appElement={document.getElementById('root')}
                className="FiltersModal"
                overlayClassName="Overlay"
            >
                <div className="ModalContent">
                    <h2>Filters</h2>
                    <hr />
                    <p>Types:</p>
                    <ColumnSelect 
                        column={table.getColumn("types")}
                        selectValue={typeFilterValue}
                        setSelectValue={setTypeFilterValue}
                    />
                    <p>Abilities:</p>
                    <ColumnSelect 
                        column={table.getColumn("abilities")}
                        selectValue={abilityFilterValue}
                        setSelectValue={setAbilityFilterValue}
                    />
                    <p>Moves:</p>
                    <ColumnSelect 
                        column={table.getColumn("learnset")}
                        selectValue={learnsetFilterValue}
                        setSelectValue={setLearnsetFilterValue}
                    />
                    <button className="ModalCloseButton" onClick={handleClose}>Close</button>
                </div>
            </Modal>
            <hr />
            <table>
                <thead>
                    {table.getHeaderGroups().map((header) => {
                        return (
                            <tr key={header.id}>
                                {header.headers.map((col) => {
                                    return (
                                        <th
                                            className={col.id}
                                            key={col.id} 
                                            onClick={col.column.getToggleSortingHandler()
                                        }>
                                            {flexRender(col.column.columnDef.header, col.getContext())}
                                        </th>
                                    );
                                })}
                            </tr>
                        );
                    })}
                </thead>
                <tbody>
                    {table.getRowModel().rows.map((row) => {
                        return (
                            <tr key={row.id} className={row.original["isDrafted"] ? "drafted" : "undrafted"}>
                                {row.getVisibleCells().map(cell => {
                                    return (
                                        <td 
                                            className={cell.column.id}
                                            key={cell.id}
                                        >
                                            {flexRender(cell.column.columnDef.cell, cell.getContext())}
                                        </td>
                                    );
                                })}
                            </tr>
                        );
                    })}
                </tbody>
            </table>
        </>
    );
};

export default Table